import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams, StructuredOutputParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const createSession = (): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
});

const providerRejecting = (rejection: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
    throw rejection;
  },
  async generateStructured<T>(_params: StructuredOutputParams<T>): Promise<T> {
    return {} as T;
  },
});

describe('ChatOrchestrator non-Error rejection handling', () => {
  it.each([['a string rejection', 'provider rejected'], ['a plain-object rejection', {code: 'UNAVAILABLE'}], ['an undefined rejection', undefined]])(
    'calls onError once with an Error caused by %s while preserving the caller rejection',
    async (_name, rejection: unknown) => {
      const received: Error[] = [];
      const orchestrator = createChatOrchestrator(providerRejecting(rejection), promptBuilder, undefined, {
        hooks: {
          onError: async (_session, error) => {
            received.push(error);
          },
        },
      });

      const callerRejection = await orchestrator.processMessage(createSession()).catch(error => error);

      expect({callerRejection, received}).toEqual({
        callerRejection: rejection,
        received: [expect.objectContaining({cause: rejection})],
      });
      expect(received[0]).toBeInstanceOf(Error);
    }
  );
});
## Measured semantics — out of scope

This property of `src/orchestration/chatOrchestrator.ts` is recorded so the hook features that follow specify against real behaviour. This issue does not change it; that is a separate, out-of-scope change owned by no issue in this epic.

- Every rejection calls `onError` exactly once. A rejection that is already an `Error` reaches the hook as that same instance; every other value reaches it wrapped in an `Error` whose `cause` is the original value, while the caller still receives the original rejection unchanged ([validated by: calls onError once with an Error caused by a non-Error rejection while preserving the caller rejection](../../src/orchestration/chatOrchestrator.acceptance.test.ts#L24)).
# Definition of Done

> The orchestrator's `catch` gates `onError` on `error instanceof Error`. A rejection that is not an `Error` — a thrown string, a plain object, a value from a library that rejects with its own shape — bypasses `onError` entirely while still propagating to the caller.

**Strategy: `direct`** — `createChatOrchestrator(...).processMessage()` is the real public entry point, and a provider rejection reaches its existing `catch` directly. The acceptance test observes both the hook and caller boundaries without mocks.

## Done when these pass

- [ ] **calls onError once with an Error caused by a non-Error rejection while preserving the caller rejection** — string, plain-object, and `undefined` provider rejections all notify the hook with an `Error` whose `cause` is the original value while the caller sees that exact value.
  `src/orchestration/chatOrchestrator.acceptance.test.ts`

## Facets

- [ ] Make the orchestrator notify `onError` for every rejection, wrapping only non-`Error` values with their original rejection as `cause`.
- [ ] Preserve the existing `Error` instance behavior covered by the unedited orchestrator tests.
- [ ] Replace the recorded-flaw prose in the config-hooks spec with the guarantee and add the consumer-facing CHANGELOG entry.

## Out of scope

- `beforeSession` escaping the `try` and usage accounting across tool rounds.
